import React, { useEffect, useState } from "react";
import "./YouTube.css";

const API_KEY = "YOUR_YOUTUBE_API_KEY"; // Replace with your YouTube API Key
const MAX_RESULTS = 5; // Number of videos to show

const YouTube = ({ searchQuery }) => {
  const [videos, setVideos] = useState([]);

  useEffect(() => {
    if (!searchQuery) return;

    const fetchVideos = async () => {
      try {
        const response = await fetch(
          `https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(
            searchQuery
          )}&type=video&maxResults=${MAX_RESULTS}&key=${API_KEY}`
        );

        const data = await response.json();

        if (data.items) {
          setVideos(data.items);
        }
      } catch (error) {
        console.error("Error fetching YouTube videos:", error);
      }
    };

    fetchVideos();
  }, [searchQuery]); // Runs when searchQuery changes

  return (
    <div className="youtube-page">
      <h2>📺 YouTube Learning</h2>
      <p>Showing results for: <strong>{searchQuery}</strong></p>

      <div className="video-grid">
        {videos.length > 0 ? (
          videos.map((video) => (
            <div key={video.id.videoId} className="video-container">
              <iframe
                width="360"
                height="200"
                src={`https://www.youtube.com/embed/${video.id.videoId}`}
                title={video.snippet.title}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              ></iframe>
              <p>{video.snippet.title}</p>
            </div>
          ))
        ) : (
          <p>No videos found for "{searchQuery}"</p>
        )}
      </div>
    </div>
  );
};

export default YouTube;
